public struct DelegationNote: Codable, Equatable, Sendable {
    /// The child the note is about. A `parentMessage` names the child it sits in.
    public var childConversationID: ConversationID
    /// Who wrote it: the child's named agent, or for a `parentMessage` the parent's agent.
    public var childName: String
    public var kind: DelegationNoteKind
    /// How a report's turn ended; a message is `completed`.
    public var state: DelegationNoteState
    /// About 400 characters of the child's final message, or of the message.
    public var excerpt: String
    /// The child reached its cap of automatic follow-ups, so the note waits for the user's next message or Continue.
    public var waitsForUser: Bool
    /// A report of a turn the user drove in the child. It wakes no one and rides on the parent's next run, unless the user sends it on.
    public var deferred: Bool
    /// The child's turn a report is of.
    public var runID: ConversationRunID?
    /// Why a `stopped` turn stopped.
    public var stopCause: DelegationStopCause?

    public init(
        childConversationID: ConversationID,
        childName: String,
        kind: DelegationNoteKind,
        state: DelegationNoteState,
        excerpt: String,
