        deferred: Bool,
        runID: ConversationRunID? = nil,
        stopCause: DelegationStopCause? = nil
    ) {
        self.childConversationID = childConversationID
        self.childName = childName
        self.kind = kind
        self.state = state
        self.excerpt = excerpt
        self.waitsForUser = waitsForUser
        self.deferred = deferred
        self.runID = runID
        self.stopCause = stopCause
    }

    private enum CodingKeys: String, CodingKey {
        case childConversationID
        case childName
        case kind
        case state
        case excerpt
        case waitsForUser
        case deferred
        case runID
        case stopCause
    }

    public init(from decoder: Decoder) throws {
        let container = try decoder.container(keyedBy: CodingKeys.self)
        childConversationID = try container.decode(ConversationID.self, forKey: .childConversationID)
        childName = try container.decode(String.self, forKey: .childName)
        kind = try container.decodeIfPresent(DelegationNoteKind.self, forKey: .kind) ?? .report
        state = try container.decode(DelegationNoteState.self, forKey: .state)
        excerpt = try container.decode(String.self, forKey: .excerpt)
        waitsForUser = try container.decodeIfPresent(Bool.self, forKey: .waitsForUser) ?? false
        deferred = try container.decodeIfPresent(Bool.self, forKey: .deferred) ?? false
        runID = try container.decodeIfPresent(ConversationRunID.self, forKey: .runID)
        stopCause = try container.decodeIfPresent(DelegationStopCause.self, forKey: .stopCause)
    }
}

