public struct EngineSummary: Codable, Equatable, Sendable {
    public var engineID: EngineID
    public var displayName: String
    /// The client's icon key, as `agent.list` sends it. Absent, or a key the client does not know, means a monogram.
    public var brand: String?
    public var authState: EngineAuthState
    public var installState: EngineInstallState
    public var capabilities: [EngineCapability]
    public var models: [EngineModelOption]
    /// The model the agent runs when no explicit model is requested, as observed on the most recent session/new (the model select's current value). None when the agent advertises no model options.
    public var defaultModelID: String?
    /// Permission/collaboration modes the agent advertises on `session/new` (ACP `category: mode` config option). Empty when the agent has none or none has been observed yet.
    public var modes: [EngineSelectOption]
    /// The mode select's current value on the most recent `session/new` — what the agent runs when the client requests nothing.
    public var defaultModeID: String?
    /// Thought/reasoning effort levels the agent advertises on `session/new` (ACP `category: thought_level` config option).
    public var thoughtLevels: [EngineSelectOption]
    public var defaultThoughtLevelID: String?
    public var steeringCapability: SteeringCapability
    /// Sign-ins the agent advertises, for a client that wants to offer one before any adapter is running. Empty is not "no sign-in exists" — it is "none has been observed yet", which is the ordinary state on a cold launch. Never required: an older client's `EngineSummary` decodes fine without it.
    public var authMethods: [AgentAuthMethod]
    /// Node/npx health behind a harness engine. `install_state` says only whether the engine is usable; this says why it is not, which is what a client needs to tell the user what to install. None for engines with no runtime of their own, and from a server predating this field.
    public var runtime: AgentRuntimeStatus?

    public init(
        engineID: EngineID,
        displayName: String,
        brand: String? = nil,
        authState: EngineAuthState,
        installState: EngineInstallState,
        capabilities: [EngineCapability],
        models: [EngineModelOption],
        defaultModelID: String? = nil,
        modes: [EngineSelectOption],
        defaultModeID: String? = nil,
        thoughtLevels: [EngineSelectOption],
        defaultThoughtLevelID: String? = nil,
        steeringCapability: SteeringCapability,
        authMethods: [AgentAuthMethod],
        runtime: AgentRuntimeStatus? = nil
    ) {
        self.engineID = engineID
        self.displayName = displayName
        self.brand = brand
        self.authState = authState
        self.installState = installState
        self.capabilities = capabilities
        self.models = models
        self.defaultModelID = defaultModelID
        self.modes = modes
        self.defaultModeID = defaultModeID
        self.thoughtLevels = thoughtLevels
        self.defaultThoughtLevelID = defaultThoughtLevelID
        self.steeringCapability = steeringCapability
        self.authMethods = authMethods
        self.runtime = runtime
    }

    private enum CodingKeys: String, CodingKey {
        case engineID
        case displayName
        case brand
        case authState
        case installState
        case capabilities
        case models
        case defaultModelID
        case modes
        case defaultModeID
        case thoughtLevels
        case defaultThoughtLevelID
        case steeringCapability
        case authMethods
        case runtime
    }

    public init(from decoder: Decoder) throws {
        let container = try decoder.container(keyedBy: CodingKeys.self)
        engineID = try container.decode(EngineID.self, forKey: .engineID)
        displayName = try container.decode(String.self, forKey: .displayName)
        brand = try container.decodeIfPresent(String.self, forKey: .brand)
        authState = try container.decode(EngineAuthState.self, forKey: .authState)
        installState = try container.decode(EngineInstallState.self, forKey: .installState)
        capabilities = try container.decodeIfPresent([EngineCapability].self, forKey: .capabilities) ?? []
        // Tolerate a bundled core binary that predates model catalogs.
        models = try container.decodeIfPresent([EngineModelOption].self, forKey: .models) ?? []
        defaultModelID = try container.decodeIfPresent(String.self, forKey: .defaultModelID)
        modes = try container.decodeIfPresent([EngineSelectOption].self, forKey: .modes) ?? []
        defaultModeID = try container.decodeIfPresent(String.self, forKey: .defaultModeID)
        thoughtLevels = try container.decodeIfPresent([EngineSelectOption].self, forKey: .thoughtLevels) ?? []
        defaultThoughtLevelID = try container.decodeIfPresent(String.self, forKey: .defaultThoughtLevelID)
        steeringCapability = try container.decodeIfPresent(SteeringCapability.self, forKey: .steeringCapability) ?? .unsupported
        authMethods = try container.decodeIfPresent([AgentAuthMethod].self, forKey: .authMethods) ?? []
        runtime = try container.decodeIfPresent(AgentRuntimeStatus.self, forKey: .runtime)
    }
}

