public struct AgentSummary: Codable, Equatable, Sendable {
    /// Advisory snapshot; layout changes still enforce claiming transactionally.
    public var canSetLayout: Bool?
    public var harnessID: String?
    public var label: String?
    public var homeKind: AgentHomeKind?
    public var agentID: AgentID
    /// The product name ("Claude Code"); `engine.list` uses the same one.
    public var displayName: String
    public var vendorName: String
    /// The vendor CLI's own config dir ("~/.claude"), for a hint about carrying an existing setup over. Absent when there is none.
    public var vendorHome: String?
    /// The client's icon key. Absent, or a key the client does not know, means a monogram.
    public var brand: String?
    /// What signing in connects ("ChatGPT account").
    public var accountLabel: String
    public var accountKind: AgentAccountKind
    /// A `multiProvider` agent's providers the user set up, sorted, read off its last-seen model IDs (`provider/model`). Providers the agent lists with no setup (omp's on-device `apple`) are left out, so an agent can be signed in with none. Absent for other account kinds and before the agent's models were ever seen.
    public var modelProviders: [String]?
    public var runtime: AgentRuntimeStatus
    public var adapter: AgentAdapterStatus
    /// The pinned npm package this agent's adapter runs at. Statically known, so it is the one version a client can show before the adapter has ever started — `adapter.agent_version` is the ACP agent's self-report from `initialize` and is absent until then. `None` for agents launched some other way (the in-process test agent).
    public var adapterPackage: AgentAdapterPackage?

    public init(
        canSetLayout: Bool? = nil,
        harnessID: String? = nil,
        label: String? = nil,
        homeKind: AgentHomeKind? = nil,
        agentID: AgentID,
        displayName: String,
        vendorName: String,
        vendorHome: String? = nil,
        brand: String? = nil,
        accountLabel: String,
        accountKind: AgentAccountKind,
        modelProviders: [String]? = nil,
        runtime: AgentRuntimeStatus,
        adapter: AgentAdapterStatus,
        adapterPackage: AgentAdapterPackage? = nil
    ) {
        self.canSetLayout = canSetLayout
        self.harnessID = harnessID
        self.label = label
        self.homeKind = homeKind
        self.agentID = agentID
        self.displayName = displayName
        self.vendorName = vendorName
        self.vendorHome = vendorHome
        self.brand = brand
        self.accountLabel = accountLabel
        self.accountKind = accountKind
        self.modelProviders = modelProviders
        self.runtime = runtime
        self.adapter = adapter
        self.adapterPackage = adapterPackage
    }
}

public struct AgentAdapterStatus: Codable, Equatable, Sendable {
    public var lifecycle: AgentLifecycleState
    public var authState: AgentAuthState
    public var authMethods: [AgentAuthMethod]
    public var agentName: String?
    public var agentVersion: String?
    public var steeringCapability: SteeringCapability
    /// Mirrors the ACP agent's `promptCapabilities.image` from `initialize`.
    public var supportsImageInput: Bool
    /// One row per ACP surface core knows, joining what the SDK defines, what this agent advertised on `initialize`, and what Ottam's client implements. Rows are always present; the agent column is absent until the agent has been probed once.
    public var compatibility: [AgentFeatureCompatibility]
    /// This adapter generation was seen authenticated at least once, so a later `authState: missing` means credentials lapsed rather than were never present. Consumers use it only to word the difference.
    public var credentialsSeen: Bool
    public var generation: UInt64
    public var lastError: String?

    public init(
        lifecycle: AgentLifecycleState,
        authState: AgentAuthState,
        authMethods: [AgentAuthMethod],
        agentName: String? = nil,
        agentVersion: String? = nil,
        steeringCapability: SteeringCapability,
        supportsImageInput: Bool,
        compatibility: [AgentFeatureCompatibility],
        credentialsSeen: Bool,
        generation: UInt64,
        lastError: String? = nil
    ) {
        self.lifecycle = lifecycle
        self.authState = authState
        self.authMethods = authMethods
        self.agentName = agentName
        self.agentVersion = agentVersion
        self.steeringCapability = steeringCapability
        self.supportsImageInput = supportsImageInput
        self.compatibility = compatibility
        self.credentialsSeen = credentialsSeen
        self.generation = generation
        self.lastError = lastError
    }

    private enum CodingKeys: String, CodingKey {
        case lifecycle
        case authState
        case authMethods
        case agentName
        case agentVersion
        case steeringCapability
        case supportsImageInput
        case compatibility
        case credentialsSeen
        case generation
        case lastError
    }

    public init(from decoder: Decoder) throws {
        let container = try decoder.container(keyedBy: CodingKeys.self)
        lifecycle = try container.decode(AgentLifecycleState.self, forKey: .lifecycle)
        authState = try container.decode(AgentAuthState.self, forKey: .authState)
        authMethods = try container.decodeIfPresent([AgentAuthMethod].self, forKey: .authMethods) ?? []
        agentName = try container.decodeIfPresent(String.self, forKey: .agentName)
        agentVersion = try container.decodeIfPresent(String.self, forKey: .agentVersion)
        steeringCapability = try container.decodeIfPresent(SteeringCapability.self, forKey: .steeringCapability) ?? .unsupported
        supportsImageInput = try container.decodeIfPresent(Bool.self, forKey: .supportsImageInput) ?? false
        compatibility = try container.decodeIfPresent([AgentFeatureCompatibility].self, forKey: .compatibility) ?? []
        credentialsSeen = try container.decodeIfPresent(Bool.self, forKey: .credentialsSeen) ?? false
        generation = try container.decode(UInt64.self, forKey: .generation)
        lastError = try container.decodeIfPresent(String.self, forKey: .lastError)
    }
}

