    /// What the agent said on `initialize`; absent when not judgeable there.
    public var agentAdvertises: Bool?
    public var clientSupport: AgentFeatureClientSupport
    /// Which part is handled, for `Partial` rows.
    public var clientDetail: String?
    public var verdict: AgentFeatureVerdict

    public init(
        feature: String,
        group: AgentFeatureGroup,
        sdkStatus: AgentFeatureSdkStatus,
        sdkDetail: String? = nil,
