}

public struct AgentAdapterPackage: Codable, Equatable, Sendable {
    public var name: String
    public var version: String
    /// How the pin is installed. Absent means `npm` (a server predating binary adapters).
    public var source: AgentAdapterSource
    /// Whether a launchable version is installed in Ottam's managed store: this pin, or an older one standing in while an app update's pin installs (see `installedVersion`, `update`). Install is mandatory: a `notInstalled` adapter's engine is unusable until `agent.install` completes. Defaults to `installed` when absent (a server predating managed installs launched via npx on demand).
    public var installState: AgentAdapterInstallState
    /// The version that launches now. Equals `version` once the pin is installed; an older version while `update` is present.
    public var installedVersion: String?
    /// Present while an older installed version stands in for this pin.
    public var update: AgentUpdateStatus?

    public init(
        name: String,
        version: String,
        source: AgentAdapterSource,
        installState: AgentAdapterInstallState,
        installedVersion: String? = nil,
        update: AgentUpdateStatus? = nil
    ) {
        self.name = name
        self.version = version
        self.source = source
        self.installState = installState
        self.installedVersion = installedVersion
        self.update = update
    }

    private enum CodingKeys: String, CodingKey {
        case name
        case version
        case source
        case installState
        case installedVersion
        case update
    }

    public init(from decoder: Decoder) throws {
        let container = try decoder.container(keyedBy: CodingKeys.self)
        name = try container.decode(String.self, forKey: .name)
        version = try container.decode(String.self, forKey: .version)
        source = try container.decodeIfPresent(AgentAdapterSource.self, forKey: .source) ?? .npm
        installState = try container.decodeIfPresent(AgentAdapterInstallState.self, forKey: .installState) ?? .installed
        installedVersion = try container.decodeIfPresent(String.self, forKey: .installedVersion)
        update = try container.decodeIfPresent(AgentUpdateStatus.self, forKey: .update)
    }
}

