public struct AgentSignInEventParams: Codable, Equatable, Sendable {
    public var agentID: AgentID
    public var authSessionID: AgentAuthSessionID
    public var delivery: AgentAuthDelivery
    public var phase: AgentAuthPhase
    /// The login needs to be seen. Latches on: once core has asked for the terminal to be shown, later events keep asking, so a client that missed one event still ends up showing it.
    public var revealTerminal: Bool
    /// Present for `clientTerminal` from the first event, whether or not `revealTerminal` is set yet.
    public var terminal: AgentAuthTerminal?
    public var error: String?

    public init(
        agentID: AgentID,
        authSessionID: AgentAuthSessionID,
        delivery: AgentAuthDelivery,
        phase: AgentAuthPhase,
        revealTerminal: Bool,
        terminal: AgentAuthTerminal? = nil,
        error: String? = nil
    ) {
        self.agentID = agentID
        self.authSessionID = authSessionID
        self.delivery = delivery
        self.phase = phase
        self.revealTerminal = revealTerminal
        self.terminal = terminal
        self.error = error
    }

    private enum CodingKeys: String, CodingKey {
        case agentID
        case authSessionID
        case delivery
        case phase
        case revealTerminal
        case terminal
        case error
    }

    public init(from decoder: Decoder) throws {
        let container = try decoder.container(keyedBy: CodingKeys.self)
        agentID = try container.decode(AgentID.self, forKey: .agentID)
        authSessionID = try container.decode(AgentAuthSessionID.self, forKey: .authSessionID)
        delivery = try container.decode(AgentAuthDelivery.self, forKey: .delivery)
        phase = try container.decode(AgentAuthPhase.self, forKey: .phase)
        revealTerminal = try container.decodeIfPresent(Bool.self, forKey: .revealTerminal) ?? false
        terminal = try container.decodeIfPresent(AgentAuthTerminal.self, forKey: .terminal)
        error = try container.decodeIfPresent(String.self, forKey: .error)
    }
}

