public struct ConversationSummary: Codable, Equatable, Sendable {
    public var conversationID: ConversationID
    public var workspaceID: WorkspaceID
    public var workingRoot: WorkingRootSummary
    public var title: String
    public var createdAt: String
    public var updatedAt: String
    /// Ottam answers this conversation's tool permission requests itself (allow once) for agents without a bypass mode of their own.
    public var alwaysAllowToolActions: Bool
    /// The conversation that delegated this one. Absent for a top-level conversation, and for a child whose parent was deleted.
    public var parentConversationID: ConversationID?
    /// The agent a delegated child was started as: a named agent's name, or an installed agent's display name for a child started ad hoc.
    public var delegatedAgentName: String?
    /// The task a delegated child was given, as its parent named it.
    public var delegatedTaskTitle: String?
    /// The seed a delegated child's tile is drawn from: its own for a child started ad hoc, or its named agent's current one. Absent for a named agent without one, whose tile clients draw from `delegatedAgentName`.
    public var delegatedAvatarSeed: Int?
    /// The first 16 hex digits of the SHA-256 of the delegated prompt, trimmed, so the parent's `delegate` tool call finds this child.
    public var delegationKey: String?
    /// The parent's run whose `delegate` call started this child. A client shows the child's card in that run when no tool call in it is recognizably `delegate`, as when OpenCode runs MCP tools inside its code-mode `execute`. Absent for children from before it was kept.
    public var delegatedFromRunID: ConversationRunID?
    /// A delegated child's latest turn, for its card in the parent.
    public var delegationActivity: DelegationActivity?
    /// A delegated child's latest turn whose report waits in its parent without waking it, because the user drove it; that turn offers Send to Parent.
    public var deferredReportRunID: ConversationRunID?

    public init(
        conversationID: ConversationID,
        workspaceID: WorkspaceID,
        workingRoot: WorkingRootSummary,
        title: String,
        createdAt: String,
        updatedAt: String,
        alwaysAllowToolActions: Bool,
        parentConversationID: ConversationID? = nil,
        delegatedAgentName: String? = nil,
        delegatedTaskTitle: String? = nil,
        delegatedAvatarSeed: Int? = nil,
        delegationKey: String? = nil,
        delegatedFromRunID: ConversationRunID? = nil,
        delegationActivity: DelegationActivity? = nil,
        deferredReportRunID: ConversationRunID? = nil
    ) {
        self.conversationID = conversationID
        self.workspaceID = workspaceID
        self.workingRoot = workingRoot
        self.title = title
        self.createdAt = createdAt
        self.updatedAt = updatedAt
        self.alwaysAllowToolActions = alwaysAllowToolActions
        self.parentConversationID = parentConversationID
        self.delegatedAgentName = delegatedAgentName
        self.delegatedTaskTitle = delegatedTaskTitle
        self.delegatedAvatarSeed = delegatedAvatarSeed
        self.delegationKey = delegationKey
        self.delegatedFromRunID = delegatedFromRunID
        self.delegationActivity = delegationActivity
        self.deferredReportRunID = deferredReportRunID
    }

    private enum CodingKeys: String, CodingKey {
        case conversationID
        case workspaceID
        case workingRoot
        case title
        case createdAt
        case updatedAt
        case alwaysAllowToolActions
        case parentConversationID
        case delegatedAgentName
        case delegatedTaskTitle
        case delegatedAvatarSeed
        case delegationKey
        case delegatedFromRunID
        case delegationActivity
        case deferredReportRunID
    }

    public init(from decoder: Decoder) throws {
        let container = try decoder.container(keyedBy: CodingKeys.self)
        conversationID = try container.decode(ConversationID.self, forKey: .conversationID)
        workspaceID = try container.decode(WorkspaceID.self, forKey: .workspaceID)
        workingRoot = try container.decode(WorkingRootSummary.self, forKey: .workingRoot)
        title = try container.decode(String.self, forKey: .title)
        createdAt = try container.decode(String.self, forKey: .createdAt)
        updatedAt = try container.decode(String.self, forKey: .updatedAt)
        alwaysAllowToolActions = try container.decodeIfPresent(Bool.self, forKey: .alwaysAllowToolActions) ?? false
        parentConversationID = try container.decodeIfPresent(ConversationID.self, forKey: .parentConversationID)
        delegatedAgentName = try container.decodeIfPresent(String.self, forKey: .delegatedAgentName)
        delegatedTaskTitle = try container.decodeIfPresent(String.self, forKey: .delegatedTaskTitle)
        delegatedAvatarSeed = try container.decodeIfPresent(Int.self, forKey: .delegatedAvatarSeed)
        delegationKey = try container.decodeIfPresent(String.self, forKey: .delegationKey)
        delegatedFromRunID = try container.decodeIfPresent(ConversationRunID.self, forKey: .delegatedFromRunID)
        delegationActivity = try container.decodeIfPresent(DelegationActivity.self, forKey: .delegationActivity)
        deferredReportRunID = try container.decodeIfPresent(ConversationRunID.self, forKey: .deferredReportRunID)
    }
}

