/// One run of a Conversation: the engine and settings it ran with, its status,
/// the harness session it ran on, and whether the user or the agent started it.
public struct ConversationRunSummary: Codable, Equatable, Sendable {
    public var runID: ConversationRunID
    public var conversationID: ConversationID
    public var engineID: EngineID
    public var modelID: String?
    /// The mode this run was started with, so a retry can be launched the same way rather than falling back to the adapter's default — which is how a run the user restricted comes back more permissive than they chose. None for runs started before this was recorded, and for runs that requested no mode.
    public var modeID: String?
    /// The thought/effort level this run was started with. Recorded for the same reason as `mode_id`.
    public var thoughtLevelID: String?
    public var status: ConversationRunStatus
    public var startedAt: String
    public var completedAt: String?
    public var agentSessionID: AgentSessionID?
    public var sessionOrigin: SessionOrigin?
    /// Who started the run. A core that predates autonomous runs omits it; all its runs are the user's.
    public var origin: RunOrigin
    public var stopReason: AgentStopReason?
    public var cost: JSONValue
    /// Tokens the run's turn used. Absent for runs before this was recorded, and for a turn whose answer never came.
    public var usage: ConversationRunUsage?
    /// A finished run whose answer has reported no usage. False for runs from before usage was recorded. A stopped run's late answer can still clear it, with a `usage` event.
    public var usageUnavailable: Bool
    /// The earlier turns this run's prompt carried to a session that had not seen them, such as one opened after switching agents. Absent when it carried none.
    public var historyReplay: ConversationHistoryReplay?
    public var error: JSONValue

    public init(
        runID: ConversationRunID,
        conversationID: ConversationID,
        engineID: EngineID,
        modelID: String? = nil,
        modeID: String? = nil,
        thoughtLevelID: String? = nil,
        status: ConversationRunStatus,
        startedAt: String,
        completedAt: String? = nil,
        agentSessionID: AgentSessionID? = nil,
        sessionOrigin: SessionOrigin? = nil,
        origin: RunOrigin = .user,
        stopReason: AgentStopReason? = nil,
        cost: JSONValue,
        usage: ConversationRunUsage? = nil,
        usageUnavailable: Bool = false,
        historyReplay: ConversationHistoryReplay? = nil,
        error: JSONValue
    ) {
        self.runID = runID
        self.conversationID = conversationID
        self.engineID = engineID
        self.modelID = modelID
        self.modeID = modeID
        self.thoughtLevelID = thoughtLevelID
        self.status = status
        self.startedAt = startedAt
        self.completedAt = completedAt
        self.agentSessionID = agentSessionID
        self.sessionOrigin = sessionOrigin
        self.origin = origin
        self.stopReason = stopReason
        self.cost = cost
        self.usage = usage
        self.usageUnavailable = usageUnavailable
        self.historyReplay = historyReplay
        self.error = error
    }

    private enum CodingKeys: String, CodingKey {
        case runID
        case conversationID
        case engineID
        case modelID
        case modeID
        case thoughtLevelID
        case status
        case startedAt
        case completedAt
        case agentSessionID
        case sessionOrigin
        case origin
        case stopReason
        case cost
        case usage
        case usageUnavailable
        case historyReplay
        case error
    }

    public init(from decoder: Decoder) throws {
        let container = try decoder.container(keyedBy: CodingKeys.self)
        runID = try container.decode(ConversationRunID.self, forKey: .runID)
        conversationID = try container.decode(ConversationID.self, forKey: .conversationID)
        engineID = try container.decode(EngineID.self, forKey: .engineID)
        modelID = try container.decodeIfPresent(String.self, forKey: .modelID)
        modeID = try container.decodeIfPresent(String.self, forKey: .modeID)
        thoughtLevelID = try container.decodeIfPresent(String.self, forKey: .thoughtLevelID)
        status = try container.decode(ConversationRunStatus.self, forKey: .status)
        startedAt = try container.decode(String.self, forKey: .startedAt)
        completedAt = try container.decodeIfPresent(String.self, forKey: .completedAt)
        agentSessionID = try container.decodeIfPresent(AgentSessionID.self, forKey: .agentSessionID)
        sessionOrigin = try container.decodeIfPresent(SessionOrigin.self, forKey: .sessionOrigin)
        origin = try container.decodeIfPresent(RunOrigin.self, forKey: .origin) ?? .user
        stopReason = try container.decodeIfPresent(AgentStopReason.self, forKey: .stopReason)
        cost = try container.decodeIfPresent(JSONValue.self, forKey: .cost) ?? .null
        usage = try container.decodeIfPresent(ConversationRunUsage.self, forKey: .usage)
        usageUnavailable = try container.decodeIfPresent(Bool.self, forKey: .usageUnavailable) ?? false
        historyReplay = try container.decodeIfPresent(ConversationHistoryReplay.self, forKey: .historyReplay)
        error = try container.decodeIfPresent(JSONValue.self, forKey: .error) ?? .null
    }
}

