            self = .submitted(
                answers: try container.decode([AgentQuestionAnswer].self, forKey: .answers)
            )
        case .skipped:
            self = .skipped
        case .cancelled:
            self = .cancelled
        }
    }

    public func encode(to encoder: Encoder) throws {
        var container = encoder.container(keyedBy: CodingKeys.self)
        switch self {
        case .submitted(let answers):
            try container.encode(Kind.submitted, forKey: .outcome)
            try container.encode(answers, forKey: .answers)
        case .skipped:
            try container.encode(Kind.skipped, forKey: .outcome)
        case .cancelled:
            try container.encode(Kind.cancelled, forKey: .outcome)
        }
    }
}

