public enum RunInputDeliveryResolution: Codable, Equatable, Sendable {
    case retry(idempotencyKey: String)
    case markDelivered

    private enum CodingKeys: String, CodingKey { case action, idempotencyKey }
    private enum Kind: String, Codable { case retry, markDelivered }

    public init(from decoder: Decoder) throws {
        let container = try decoder.container(keyedBy: CodingKeys.self)
        switch try container.decode(Kind.self, forKey: .action) {
        case .retry:
            self = .retry(
                idempotencyKey: try container.decode(String.self, forKey: .idempotencyKey)
            )
        case .markDelivered:
            self = .markDelivered
        }
    }

    public func encode(to encoder: Encoder) throws {
        var container = encoder.container(keyedBy: CodingKeys.self)
        switch self {
        case .retry(let idempotencyKey):
            try container.encode(Kind.retry, forKey: .action)
            try container.encode(idempotencyKey, forKey: .idempotencyKey)
        case .markDelivered:
            try container.encode(Kind.markDelivered, forKey: .action)
        }
    }
}
